import { createContainer } from '../container'
import {
  AwilixInitializationError,
  AwilixNotInitializedError,
  AwilixResolutionError,
} from '../errors'
import { InjectionMode } from '../injection-mode'
import { asClass, asFunction } from '../resolvers'

describe('container initialization', () => {
  it('initializes dependencies in levels and reports metrics', async () => {
    const events: Array<string> = []
    class Database {
      async connect() {
        events.push('database')
      }
    }
    class Service {
      constructor(readonly database: Database) {}
    }
    const container = createContainer({ injectionMode: InjectionMode.CLASSIC }).register({
      database: asClass(Database)
        .singleton()
        .initializer(async (database) => {
          await database.connect()
        }),
      service: asClass(Service)
        .singleton()
        .initializer(() => {
          events.push('service')
        }),
    })

    expect(() => container.resolve('database')).toThrow(AwilixNotInitializedError)
    const result = await container.initialize({ concurrency: 5 })
    expect(events).toEqual(['database', 'service'])
    expect(result.totalDuration).toEqual(expect.any(Number))
    expect(result.metrics.database.level).toBe(0)
    expect(result.metrics.service.level).toBe(1)
    expect(result.metrics.database.duration).toEqual(expect.any(Number))
    expect(await container.initialize()).toBe(result)
  })

  it('limits parallel work within a level', async () => {
    let active = 0
    let maximum = 0
    const initialize = async () => {
      active++
      maximum = Math.max(maximum, active)
      await Promise.resolve()
      active--
    }
    const container = createContainer({ injectionMode: InjectionMode.CLASSIC }).register({
      first: asFunction(() => ({})).singleton().initializer(initialize),
      second: asFunction(() => ({})).singleton().initializer(initialize),
      third: asFunction(() => ({})).singleton().initializer(initialize),
    })

    await container.initialize({ concurrency: 2 })
    expect(maximum).toBe(2)
  })

  it('rolls back completed services without replacing the original failure', async () => {
    const disposed: Array<string> = []
    const original = new Error('connection failed')
    const container = createContainer().register({
      first: asFunction(() => ({ id: 'first' }))
        .singleton()
        .initializer(() => undefined)
        .disposer(() => disposed.push('first')),
      second: asFunction((first: object) => ({ id: 'second', first }))
        .singleton()
        .initializer(async () => undefined)
        .disposer(() => {
          disposed.push('second')
          throw new Error('ignore me')
        }),
      third: asFunction((second: object) => second)
        .singleton()
        .initializer(() => {
          throw original
        }),
    })

    await expect(container.initialize()).rejects.toMatchObject({
      name: 'AwilixInitializationError',
      cause: original,
    })
    expect(disposed).toEqual(['second', 'first'])
    await expect(container.initialize()).rejects.toThrow(/previously failed|Cannot re-initialize/)
  })

  it('allows graph-build failures to be retried', async () => {
